import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { CONFIG_FILE, ConfigError, defaultLitePath, effectiveLitePath, readConfig, sessionEnv, svnWorkingCopyPath, validateConfig, writeConfig } from './adapter.ts';

let base: string;
let root: string;

function makeDocsPlugin( dir: string ): string {
	mkdirSync( path.join( dir, 'docs-user' ), { recursive: true } );
	writeFileSync( path.join( dir, 'package.json' ), '{}' );
	return dir;
}

function makeLite( dir: string ): string {
	mkdirSync( dir, { recursive: true } );
	writeFileSync( path.join( dir, 'stripe-checkout.php' ), '<?php' );
	return dir;
}

beforeEach( () => {
	base = mkdtempSync( path.join( tmpdir(), 'release-console-config-' ) );
	root = path.join( base, 'wp-simple-pay-pro' );
	mkdirSync( root );
} );

afterEach( () => rmSync( base, { recursive: true, force: true } ) );

describe( 'readConfig', () => {
	it( 'returns empty settings when there is no file, or it is corrupt', () => {
		expect( readConfig( root ) ).toEqual( { marketingSitePath: null, liteRepoPath: null } );

		mkdirSync( path.join( root, '.claude' ) );
		writeFileSync( path.join( root, CONFIG_FILE ), '{nope' );

		expect( readConfig( root ) ).toEqual( { marketingSitePath: null, liteRepoPath: null } );
	} );

	it( 'expands ~ and ignores blank or non-string values', () => {
		mkdirSync( path.join( root, '.claude' ) );
		writeFileSync( path.join( root, CONFIG_FILE ), JSON.stringify( { marketingSitePath: '~/site/wpsp-docs', liteRepoPath: '   ' } ) );

		expect( readConfig( root ) ).toEqual( { marketingSitePath: path.join( homedir(), 'site/wpsp-docs' ), liteRepoPath: null } );

		writeFileSync( path.join( root, CONFIG_FILE ), JSON.stringify( { marketingSitePath: 42, liteRepoPath: [ 'x' ] } ) );

		expect( readConfig( root ) ).toEqual( { marketingSitePath: null, liteRepoPath: null } );
	} );
} );

describe( 'validateConfig', () => {
	it( 'warns when nothing is set and Lite has not been cloned', () => {
		const issues = validateConfig( root, { marketingSitePath: null, liteRepoPath: null } );

		expect( issues.map( ( issue ) => [ issue.field, issue.level ] ) ).toEqual( [
			[ 'marketingSitePath', 'warning' ],
			[ 'liteRepoPath', 'warning' ],
		] );
	} );

	it( 'accepts a real docs plugin and the default Lite checkout', () => {
		const site = makeDocsPlugin( path.join( base, 'wpsp-docs' ) );
		makeLite( defaultLitePath( root ) );

		expect( validateConfig( root, { marketingSitePath: site, liteRepoPath: null } ) ).toEqual( [] );
	} );

	it( 'rejects a missing folder or one that is not the docs plugin', () => {
		const notDocs = path.join( base, 'something' );
		mkdirSync( notDocs );

		expect( validateConfig( root, { marketingSitePath: path.join( base, 'missing' ), liteRepoPath: null } )[ 0 ] ).toMatchObject( {
			level: 'error',
			message: expect.stringContaining( 'does not exist' ),
		} );
		expect( validateConfig( root, { marketingSitePath: notDocs, liteRepoPath: null } )[ 0 ] ).toMatchObject( {
			level: 'error',
			message: expect.stringContaining( 'does not look like the wpsp-docs plugin' ),
		} );
	} );

	it( 'refuses a Lite path that is the Pro checkout, because lite-sync deletes with rsync', () => {
		const issue = validateConfig( root, { marketingSitePath: null, liteRepoPath: root } ).find( ( item ) => item.field === 'liteRepoPath' );

		expect( issue ).toMatchObject( { level: 'error', message: expect.stringContaining( 'points at this Pro checkout' ) } );
	} );

	it( 'refuses a Lite folder that is not a Lite checkout', () => {
		const other = path.join( base, 'other' );
		mkdirSync( other );

		const issue = validateConfig( root, { marketingSitePath: null, liteRepoPath: other } ).find( ( item ) => item.field === 'liteRepoPath' );

		expect( issue ).toMatchObject( { level: 'error', message: expect.stringContaining( 'not a Lite checkout' ) } );
	} );
} );

describe( 'writeConfig', () => {
	it( 'saves cleaned paths, creating the .claude folder', () => {
		const site = makeDocsPlugin( path.join( base, 'wpsp-docs' ) );
		const lite = makeLite( path.join( base, 'lite' ) );

		const saved = writeConfig( root, { marketingSitePath: `  ${ site }  `, liteRepoPath: lite } );

		expect( saved ).toEqual( { marketingSitePath: site, liteRepoPath: lite } );
		expect( JSON.parse( readFileSync( path.join( root, CONFIG_FILE ), 'utf8' ) ) ).toEqual( saved );
		expect( readConfig( root ) ).toEqual( saved );
	} );

	it( 'saves empty values as null (use the defaults)', () => {
		expect( writeConfig( root, { marketingSitePath: '', liteRepoPath: '' } ) ).toEqual( { marketingSitePath: null, liteRepoPath: null } );
	} );

	it( 'refuses to save, and writes nothing, when a path is invalid', () => {
		expect( () => writeConfig( root, { marketingSitePath: path.join( base, 'missing' ) } ) ).toThrow( ConfigError );
		expect( existsSync( path.join( root, CONFIG_FILE ) ) ).toBe( false );
	} );

	it( 'reports every error at once', () => {
		try {
			writeConfig( root, { marketingSitePath: path.join( base, 'missing' ), liteRepoPath: root } );
			throw new Error( 'expected a ConfigError' );
		} catch ( error ) {
			expect( ( error as ConfigError ).issues.map( ( issue ) => issue.field ) ).toEqual( [ 'marketingSitePath', 'liteRepoPath' ] );
		}
	} );
} );

describe( 'Lite path and session env', () => {
	it( 'defaults Lite to a sibling of the Pro checkout', () => {
		expect( effectiveLitePath( root, { marketingSitePath: null, liteRepoPath: null } ) ).toBe( path.join( base, 'wp-simple-pay-lite' ) );
		expect( effectiveLitePath( root, { marketingSitePath: null, liteRepoPath: '/x/lite' } ) ).toBe( '/x/lite' );
	} );

	it( 'finds the wp.org SVN working copy where svn-path.sh does', () => {
		expect( svnWorkingCopyPath( root, {} ) ).toBe( path.join( base, 'stripe-svn' ) );
		expect( svnWorkingCopyPath( root, { SVN_WC: '  ' } ) ).toBe( path.join( base, 'stripe-svn' ) );
		expect( svnWorkingCopyPath( root, { SVN_WC: '/x/svn' } ) ).toBe( '/x/svn' );
		expect( svnWorkingCopyPath( root, { SVN_WC: '../svn' } ) ).toBe( path.join( base, 'svn' ) );
		expect( svnWorkingCopyPath( root, { SVN_WC: '~/svn' } ) ).toBe( path.join( homedir(), 'svn' ) );
	} );

	it( 'passes a configured Lite path to sessions as LITE_REPO', () => {
		expect( sessionEnv( { marketingSitePath: null, liteRepoPath: '/x/lite' } ) ).toEqual( { LITE_REPO: '/x/lite' } );
		expect( sessionEnv( { marketingSitePath: null, liteRepoPath: null } ) ).toEqual( {} );
	} );
} );
